#!/usr/bin/env python3
"""Retain one non-registered real 8-UAV language-to-control smoke."""
from __future__ import annotations
import argparse,hashlib,json,subprocess,sys
from pathlib import Path
import yaml
from e5_trial_registry import MODES,scenarios
FIXTURE='ENG-E5-COLD-START-LANGUAGE-8UAV-v1';COMMAND='Have UAVs 1 through 8 form a circle centered at [0, 13.5, 3] with radius 8 meters in exactly 8 seconds using normal motion and safety factor 1.0.'
def fixture():
 assert COMMAND not in {x['exact_command'] for x in scenarios().values()}
 return {'runtime_spec_type':'E5_nonregistered_engineering_runtime_v1','fixture_class':'non_registered_engineering_fixture','dataset_class':'engineering_validation','trial_id':FIXTURE,'seed':990051,'scenario_id':'ENGINEERING-LANGUAGE-PLUMBING','uav_ids':[1,2,3,4,5,6,7,8],'cold_start_spawn_m':{str(i):[0.,3.*i,.83] for i in range(1,9)},'cold_start_required':True,'readiness_gate':{'required_uav_count':8,'all_px4_ready':True,'armed_offboard':True,'frozen_fresh_state_predicate':True},'full_method_modes':MODES,'exact_command':COMMAND,'exact_command_utf8_sha256':hashlib.sha256(COMMAND.encode()).hexdigest(),'command_source':'non_registered_engineering_fixture','candidate_gt_used_as_input':False,'mission_timeout_s':35.0,'metric_log_schema':{'latency_components':['LLM_inference','parse_validation','snapshot_wait','resolution','allocation','dispatch','physical_execution']}}
def main():
 p=argparse.ArgumentParser();p.add_argument('--output',type=Path,required=True);a=p.parse_args()
 if a.output.exists():raise SystemExit('output exists')
 a.output.mkdir(parents=True);raw=a.output/'raw';raw.mkdir();s=fixture();sp=raw/'runtime_spec.json';sp.write_text(json.dumps(s,indent=2,sort_keys=True)+'\n');result=raw/'physical_result.json';run=subprocess.run([sys.executable,str(Path(__file__).with_name('e5_physical_trial.py')),'--runtime-spec',str(sp),'--output',str(raw),'--result',str(result)],text=True,capture_output=True,timeout=600);(raw/'harness.stdout.log').write_text(run.stdout);(raw/'harness.stderr.log').write_text(run.stderr);physical=json.loads(result.read_text()) if result.exists() else {};language=json.loads((raw/'language_result.json').read_text()) if (raw/'language_result.json').exists() else {};prov=json.loads((raw/'runtime_provenance.json').read_text()) if (raw/'runtime_provenance.json').exists() else {};meta=yaml.safe_load((raw/'rosbag/metadata.yaml').read_text()) if (raw/'rosbag/metadata.yaml').exists() else {};counts={x['topic_metadata']['name']:x['message_count'] for x in meta.get('rosbag2_bagfile_information',{}).get('topics_with_message_count',[])};keys={'LLM_inference','parse_validation','snapshot_wait','resolution','allocation','dispatch','physical_execution'}
 checks={'backend_success':run.returncode==0 and physical.get('attempt_status')=='success','nonregistered_command':s['exact_command'] not in {x['exact_command'] for x in scenarios().values()},'nonregistered_labels':physical.get('fixture_class')=='non_registered_engineering_fixture' and physical.get('dataset_class')=='engineering_validation' and physical.get('accepted_formal_result') is False,'cold_start':physical.get('cold_start') is True,'full_method_modes':physical.get('full_method_modes')==MODES,'runtime_provenance':prov.get('status')=='PASS','all_8_readiness':language.get('fresh_state_before_language_submission') is True and language.get('fresh_state_before_runtime_dispatch') is True,'real_llm_path':language.get('llm_attempt_records',0)>=1 and (raw/'llm_raw_responses.append.jsonl').stat().st_size>0 if (raw/'llm_raw_responses.append.jsonl').exists() else False,'mission_completed':language.get('candidate_completed') is True,'latency_decomposed':set(language.get('latency_decomposition_s',{}))==keys,'candidate_gt_not_input':language.get('candidate_gt_used_as_input') is False,'no_formal_command_retry':language.get('counts',{}).get('formal_command_retry')==0,'raw_logging':all(counts.get(f'/uav{i}/control_tracking_debug',0)>0 and counts.get(f'/uav{i}/iapf_debug',0)>0 for i in range(1,9)),'commands_retained':all(counts.get(f'/uav{i}/execution_command',0)==1 for i in range(1,9))}
 m={'manifest_type':'E5_live_engineering_smoke_v1','fixture_id':FIXTURE,'fixture_registered_formal_trial':False,'command_utf8_sha256':s['exact_command_utf8_sha256'],'dataset_class':'engineering_validation','accepted_formal_result':False,'result_notice':'NOT_FORMAL_RESULT','scientific_interpretation':None,'status':'PASS' if all(checks.values()) else 'FAIL','checks':checks,'backend_result':physical};(a.output/'smoke_manifest.json').write_text(json.dumps(m,indent=2,sort_keys=True)+'\n');print(json.dumps(m,sort_keys=True));return m['status']!='PASS'
if __name__=='__main__':raise SystemExit(main())
